CREATE TABLE "escuela" (
  "id_escuela" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar(20) UNIQUE NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "activo" boolean NOT NULL DEFAULT true
);

CREATE TABLE "rol" (
  "id_rol" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar(40) UNIQUE NOT NULL,
  "nombre" varchar(120) NOT NULL,
  "descripcion" varchar(300)
);

CREATE TABLE "usuario" (
  "id_usuario" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "correo_institucional" varchar(120) UNIQUE NOT NULL,
  "clave_hash" varchar(255) NOT NULL,
  "nombre_completo" varchar(150) NOT NULL,
  "cedula" varchar(20),
  "orcid" char(19),
  "id_escuela" int,
  "activo" boolean NOT NULL DEFAULT true,
  "fecha_registro" timestamptz NOT NULL
);

CREATE TABLE "usuario_rol" (
  "id_usuario" int NOT NULL,
  "id_rol" int NOT NULL,
  "fecha_asignacion" date NOT NULL,
  PRIMARY KEY ("id_usuario", "id_rol")
);

CREATE TABLE "convocatoria" (
  "id_convocatoria" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(200) NOT NULL,
  "descripcion" text,
  "fecha_apertura" date NOT NULL,
  "fecha_cierre" date NOT NULL,
  "presupuesto_estimado" numeric(14,2),
  "estado" varchar(20) NOT NULL,
  "id_publicada_por" int,
  "fecha_publicacion" timestamptz
);

CREATE TABLE "convocatoria_hito" (
  "id_hito" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_convocatoria" int NOT NULL,
  "nombre" varchar(200) NOT NULL,
  "responsable" varchar(120) NOT NULL,
  "fecha_inicio" date NOT NULL,
  "fecha_fin" date NOT NULL,
  "orden" smallint NOT NULL
);

CREATE TABLE "propuesta" (
  "id_propuesta" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar(20) UNIQUE NOT NULL,
  "id_convocatoria" int NOT NULL,
  "id_coordinador" int NOT NULL,
  "id_escuela" int NOT NULL,
  "titulo" varchar(500) NOT NULL,
  "modalidad" varchar(40) NOT NULL,
  "fecha_inicio" date,
  "fecha_finalizacion" date,
  "fecha_envio" timestamptz,
  "resumen" text,
  "abstract_en" text,
  "problema" text,
  "objetivo_general" text,
  "estado_arte" text,
  "metodologia" text,
  "hoja_ruta" text,
  "referencias" text,
  "divulgacion" text,
  "trl_actual" smallint,
  "trl_esperado" smallint,
  "requiere_dictamen_pi" boolean NOT NULL DEFAULT false,
  "declaracion_aceptada" boolean NOT NULL DEFAULT false,
  "resguardo_repositorio" boolean NOT NULL DEFAULT false,
  "resguardo_tecnico" boolean NOT NULL DEFAULT false,
  "estado_actual" varchar(40) NOT NULL,
  "etapa_flujo" smallint NOT NULL DEFAULT 0
);

CREATE TABLE "propuesta_palabra_clave" (
  "id_palabra_clave" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "idioma" char(2) NOT NULL,
  "palabra" varchar(100) NOT NULL
);

CREATE TABLE "propuesta_pregunta_general" (
  "id_respuesta" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "numero_pregunta" smallint NOT NULL,
  "codigo_pregunta" varchar(40) NOT NULL,
  "respuesta" varchar(20) NOT NULL,
  "detalle" text
);

CREATE TABLE "propuesta_objetivo_especifico" (
  "id_objetivo" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "numero" smallint NOT NULL,
  "descripcion" text NOT NULL
);

CREATE TABLE "propuesta_participante" (
  "id_participante" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "tipo" varchar(20) NOT NULL,
  "id_usuario" int,
  "nombre_completo" varchar(150) NOT NULL,
  "orcid" char(19),
  "instancia_o_institucion" varchar(200),
  "rol_en_proyecto" varchar(80),
  "periodo_nombramiento" varchar(60),
  "iniciales" varchar(10)
);

CREATE TABLE "propuesta_participante_hora" (
  "id_participante_hora" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_participante" int NOT NULL,
  "tipo_hora" varchar(30) NOT NULL,
  "cantidad_horas" numeric(5,2) NOT NULL
);

CREATE TABLE "propuesta_presupuesto_anual" (
  "id_presupuesto" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "anio" smallint NOT NULL,
  "monto_operativo" numeric(14,2) NOT NULL DEFAULT 0,
  "monto_bienes_duraderos" numeric(14,2) NOT NULL DEFAULT 0,
  "monto_total" numeric(14,2) NOT NULL DEFAULT 0
);

CREATE TABLE "propuesta_financiamiento" (
  "id_financiamiento" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "tipo" varchar(30) NOT NULL,
  "anio" smallint NOT NULL,
  "monto" numeric(14,2) NOT NULL DEFAULT 0,
  "numero_oficio" varchar(60)
);

CREATE TABLE "propuesta_producto" (
  "id_producto" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "id_objetivo" int,
  "ambito" varchar(30) NOT NULL,
  "codigo_opcion" varchar(40) NOT NULL,
  "descripcion" varchar(500) NOT NULL,
  "cantidad" smallint NOT NULL DEFAULT 1,
  "dictamen_consecutivo" varchar(40)
);

CREATE TABLE "propuesta_documento" (
  "id_documento" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "nombre" varchar(200) NOT NULL,
  "tipo" varchar(40) NOT NULL,
  "estado" varchar(20) NOT NULL,
  "ruta_archivo" varchar(500),
  "numero_version" smallint NOT NULL DEFAULT 1,
  "fecha_carga" timestamptz
);

CREATE TABLE "propuesta_historial_estado" (
  "id_historial" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "estado_anterior" varchar(40),
  "estado_nuevo" varchar(40) NOT NULL,
  "id_usuario" int,
  "fecha_hora" timestamptz NOT NULL,
  "observacion" varchar(500)
);

CREATE TABLE "linea_investigacion" (
  "id_linea_investigacion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "propuesta_linea" (
  "id_propuesta" int NOT NULL,
  "id_linea_investigacion" int NOT NULL,
  PRIMARY KEY ("id_propuesta", "id_linea_investigacion")
);

CREATE TABLE "aspecto_etico" (
  "id_aspecto_etico" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int UNIQUE NOT NULL,
  "involucra_humanos" boolean NOT NULL DEFAULT false,
  "involucra_biodiversidad" boolean NOT NULL DEFAULT false,
  "involucra_animales" boolean NOT NULL DEFAULT false,
  "involucra_pueblos_indigenas" boolean NOT NULL DEFAULT false,
  "justificacion_exencion" text
);

CREATE TABLE "permiso_etico" (
  "id_permiso" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "ente" varchar(40) NOT NULL,
  "detalle" varchar(300),
  "estado_tramite" varchar(30) NOT NULL DEFAULT 'pendiente'
);

CREATE TABLE "actividad_plan" (
  "id_actividad" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "id_objetivo" int NOT NULL,
  "numero" smallint NOT NULL,
  "descripcion" text NOT NULL,
  "resultado_esperado" text,
  "responsabilidad" varchar(40),
  "mes_inicio" smallint,
  "duracion_meses" numeric(4,1)
);

CREATE TABLE "actividad_participante" (
  "id_actividad_participante" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_actividad" int NOT NULL,
  "id_participante" int,
  "iniciales" varchar(10),
  "responsabilidad" varchar(40)
);

CREATE TABLE "actividad_riesgo" (
  "id_riesgo" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_actividad" int NOT NULL,
  "riesgo_identificado" text NOT NULL,
  "medida_mitigacion" text NOT NULL,
  "responsable_gestion" varchar(150)
);

CREATE TABLE "dictamen_pi" (
  "id_dictamen_pi" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int UNIQUE NOT NULL,
  "id_emisor" int NOT NULL,
  "potencial_proteccion" boolean NOT NULL,
  "es_innovador" boolean NOT NULL,
  "activo_identificable" varchar(200),
  "mecanismo_pi" varchar(200),
  "novedad" text,
  "titularidad" text,
  "recomendaciones_divulgacion" text,
  "confidencialidad" text,
  "analisis_tecnico" text,
  "recomendaciones_vinculacion" text,
  "numero_oficio" varchar(40) UNIQUE,
  "fecha_dictamen" date,
  "estado" varchar(20) NOT NULL
);

CREATE TABLE "revision_expediente" (
  "id_revision" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "etapa" varchar(20) NOT NULL,
  "ciclo" smallint NOT NULL DEFAULT 1,
  "id_revisor" int NOT NULL,
  "resultado" varchar(20) NOT NULL,
  "fecha_inicio" timestamptz NOT NULL,
  "fecha_fin" timestamptz
);

CREATE TABLE "revision_checklist" (
  "id_item" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_revision" int NOT NULL,
  "codigo_item" varchar(50) NOT NULL,
  "etiqueta" varchar(180) NOT NULL,
  "obligatorio" boolean NOT NULL DEFAULT true,
  "verificado" boolean NOT NULL DEFAULT false,
  "nota" varchar(500)
);

CREATE TABLE "observacion" (
  "id_observacion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "id_revision" int,
  "etapa" varchar(20) NOT NULL,
  "seccion_formulario" varchar(70),
  "id_creada_por" int NOT NULL,
  "mensaje" text NOT NULL,
  "requiere_respuesta" boolean NOT NULL DEFAULT true,
  "fecha_creacion" timestamptz NOT NULL,
  "fecha_resolucion" timestamptz
);

CREATE TABLE "observacion_respuesta" (
  "id_respuesta" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_observacion" int NOT NULL,
  "id_usuario" int NOT NULL,
  "respuesta" text NOT NULL,
  "fecha_respuesta" timestamptz NOT NULL
);

CREATE TABLE "rubrica" (
  "id_rubrica" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo" varchar(40) UNIQUE NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "modalidad_aplica" varchar(40) NOT NULL,
  "puntaje_maximo" numeric(6,2) NOT NULL DEFAULT 100
);

CREATE TABLE "rubrica_criterio" (
  "id_criterio" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_rubrica" int NOT NULL,
  "seccion" varchar(120) NOT NULL,
  "numero" smallint NOT NULL,
  "nombre" varchar(200) NOT NULL,
  "peso" numeric(5,2) NOT NULL,
  "puntaje_maximo" numeric(5,2) NOT NULL,
  "es_obligatorio" boolean NOT NULL DEFAULT false
);

CREATE TABLE "rubrica_nivel" (
  "id_nivel" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_criterio" int NOT NULL,
  "puntaje" smallint NOT NULL,
  "etiqueta" varchar(40) NOT NULL,
  "descripcion" text NOT NULL
);

CREATE TABLE "evaluacion" (
  "id_evaluacion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "id_rubrica" int NOT NULL,
  "id_evaluador" int NOT NULL,
  "instancia" varchar(20) NOT NULL,
  "puntaje_total" numeric(6,2),
  "estado" varchar(20) NOT NULL,
  "comentarios" text,
  "fecha_envio" timestamptz
);

CREATE TABLE "evaluacion_puntaje" (
  "id_puntaje" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_evaluacion" int NOT NULL,
  "id_criterio" int NOT NULL,
  "id_nivel" int,
  "puntaje" numeric(5,2) NOT NULL,
  "puntaje_sugerido_ia" numeric(5,2),
  "justificacion" text
);

CREATE TABLE "resultado_comite" (
  "id_resultado_comite" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int UNIQUE NOT NULL,
  "recomendacion" varchar(20) NOT NULL,
  "calificacion_promedio" numeric(6,2),
  "numero_oficio" varchar(40) UNIQUE,
  "fundamento" text,
  "fecha_dictamen" date,
  "id_coordinador_comite" int
);

CREATE TABLE "sesion_consejo" (
  "id_sesion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_escuela" int NOT NULL,
  "numero_sesion" varchar(60) NOT NULL,
  "tipo" varchar(30) NOT NULL,
  "fecha_sesion" date NOT NULL
);

CREATE TABLE "aval_consejo" (
  "id_aval" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int UNIQUE NOT NULL,
  "id_sesion" int,
  "id_aprobador" int,
  "resultado" varchar(20) NOT NULL,
  "articulo" varchar(40),
  "numero_oficio" varchar(40) UNIQUE,
  "observaciones" text,
  "fecha_aval" date
);

CREATE TABLE "comunicacion_institucional" (
  "id_comunicacion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int NOT NULL,
  "tipo" varchar(40) NOT NULL,
  "id_emisor" int NOT NULL,
  "id_destinatario" int,
  "destinatario_texto" varchar(200),
  "id_documento" int,
  "confirmada" boolean NOT NULL DEFAULT false,
  "fecha_envio" timestamptz NOT NULL,
  "fecha_confirmacion" timestamptz,
  "mensaje" text
);

CREATE TABLE "resolucion_cie" (
  "id_resolucion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" int UNIQUE NOT NULL,
  "id_responsable" int,
  "resultado" varchar(20) NOT NULL,
  "numero_resolucion" varchar(40) UNIQUE NOT NULL,
  "fundamento" text,
  "fecha_resolucion" date NOT NULL
);

CREATE TABLE "notificacion" (
  "id_notificacion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario_destino" int NOT NULL,
  "id_propuesta" int,
  "titulo" varchar(200) NOT NULL,
  "mensaje" varchar(500) NOT NULL,
  "leida" boolean NOT NULL DEFAULT false,
  "fecha_hora" timestamptz NOT NULL
);

CREATE UNIQUE INDEX ON "propuesta_palabra_clave" ("id_propuesta", "idioma", "palabra");

CREATE UNIQUE INDEX ON "propuesta_pregunta_general" ("id_propuesta", "codigo_pregunta");

CREATE UNIQUE INDEX ON "propuesta_objetivo_especifico" ("id_propuesta", "numero");

CREATE UNIQUE INDEX ON "propuesta_participante_hora" ("id_participante", "tipo_hora");

CREATE UNIQUE INDEX ON "propuesta_presupuesto_anual" ("id_propuesta", "anio");

CREATE UNIQUE INDEX ON "actividad_plan" ("id_propuesta", "id_objetivo", "numero");

CREATE UNIQUE INDEX ON "revision_expediente" ("id_propuesta", "etapa", "ciclo");

CREATE UNIQUE INDEX ON "revision_checklist" ("id_revision", "codigo_item");

CREATE UNIQUE INDEX ON "rubrica_criterio" ("id_rubrica", "numero");

CREATE UNIQUE INDEX ON "rubrica_nivel" ("id_criterio", "puntaje");

CREATE UNIQUE INDEX ON "evaluacion_puntaje" ("id_evaluacion", "id_criterio");

CREATE UNIQUE INDEX ON "sesion_consejo" ("id_escuela", "numero_sesion");

COMMENT ON TABLE "escuela" IS 'Unidad académica / dependencia del TEC';

COMMENT ON COLUMN "escuela"."codigo" IS 'Ej. EIC, BIO';

COMMENT ON TABLE "rol" IS 'Roles institucionales del flujo Fondos VIE';

COMMENT ON TABLE "usuario" IS 'Persona usuaria (investigadores e instancias)';

COMMENT ON TABLE "convocatoria" IS 'Convocatoria Fondos VIE';

COMMENT ON COLUMN "convocatoria"."estado" IS 'borrador | activa | cerrada | finalizada';

COMMENT ON TABLE "convocatoria_hito" IS 'Cronograma oficial de la convocatoria (Disposiciones §6)';

COMMENT ON COLUMN "convocatoria_hito"."responsable" IS 'Ej. Comité Técnico, CIE, VIE';

COMMENT ON TABLE "propuesta" IS 'Expediente central. Keywords → propuesta_palabra_clave; horas → propuesta_participante_hora; OE en tabla hija.';

COMMENT ON COLUMN "propuesta"."modalidad" IS 'fortalecimiento | basica | aplicada | basica_aplicada | desarrollo_tecnologico';

COMMENT ON COLUMN "propuesta"."trl_actual" IS 'TRL actual 1-9; NULL si no aplica';

COMMENT ON COLUMN "propuesta"."trl_esperado" IS 'TRL esperado 1-9; NULL si no aplica';

COMMENT ON TABLE "propuesta_palabra_clave" IS 'Palabras clave ES/EN normalizadas (ya no embebidas en propuesta)';

COMMENT ON COLUMN "propuesta_palabra_clave"."idioma" IS 'es | en';

COMMENT ON COLUMN "propuesta_pregunta_general"."respuesta" IS 'si | no | parcial | total';

COMMENT ON TABLE "propuesta_objetivo_especifico" IS 'Objetivos específicos normalizados (Formulario §6 + Plan)';

COMMENT ON COLUMN "propuesta_objetivo_especifico"."numero" IS 'OE1, OE2...';

COMMENT ON TABLE "propuesta_participante" IS 'Cuadros 2 y 3. Horas semanales viven en propuesta_participante_hora.';

COMMENT ON COLUMN "propuesta_participante"."tipo" IS 'funcionario_tec | externo';

COMMENT ON COLUMN "propuesta_participante"."id_usuario" IS 'FK si es funcionario TEC registrado';

COMMENT ON COLUMN "propuesta_participante"."nombre_completo" IS 'Obligatorio para externos; denormalizado opcional para TEC';

COMMENT ON COLUMN "propuesta_participante"."iniciales" IS 'Para referenciar en plan de acción';

COMMENT ON TABLE "propuesta_participante_hora" IS 'Tipos de hora por participante; totales semanales se derivan';

COMMENT ON COLUMN "propuesta_participante_hora"."tipo_hora" IS 'VIE, VIE-Centros, CONS, REC, DOC o VIESA';

COMMENT ON TABLE "propuesta_presupuesto_anual" IS 'Cuadro 4. Desglose por OG queda en Excel adjunto.';

COMMENT ON COLUMN "propuesta_financiamiento"."tipo" IS 'externo | contrapartida | cofinanciamiento';

COMMENT ON TABLE "propuesta_producto" IS 'Productos con OE asociado (Formulario cuadros 7/10)';

COMMENT ON COLUMN "propuesta_producto"."ambito" IS 'basica_aplicada | desarrollo_tecnologico | adicional | activo_pi';

COMMENT ON TABLE "propuesta_documento" IS 'Metadatos de anexos; versionado simple en la misma fila al reemplazar';

COMMENT ON COLUMN "propuesta_documento"."tipo" IS 'formulario, plan_riesgos, presupuesto, acuerdo, carta, dictamen...';

COMMENT ON COLUMN "propuesta_documento"."estado" IS 'completo | pendiente';

COMMENT ON TABLE "propuesta_historial_estado" IS 'Timeline del expediente';

COMMENT ON TABLE "aspecto_etico" IS 'Declaración ética de admisibilidad (1:1)';

COMMENT ON TABLE "permiso_etico" IS 'Uno o más entes regulatorios por propuesta';

COMMENT ON COLUMN "permiso_etico"."ente" IS 'CEC | CONAGEBIO | CICUA | COBAB | ADI | OTRO';

COMMENT ON TABLE "actividad_plan" IS 'Fila del Plan de Acción';

COMMENT ON COLUMN "actividad_plan"."responsabilidad" IS 'ejecuta | supervisa | participa';

COMMENT ON COLUMN "actividad_plan"."mes_inicio" IS '1-36 del periodo';

COMMENT ON TABLE "actividad_participante" IS 'Participantes por actividad (Plan)';

COMMENT ON COLUMN "actividad_participante"."responsabilidad" IS 'ejecuta | supervisa | participa';

COMMENT ON TABLE "actividad_riesgo" IS 'Al menos un riesgo por actividad (requisito rúbrica/plan)';

COMMENT ON TABLE "dictamen_pi" IS 'Dictamen Centro de Vinculación';

COMMENT ON COLUMN "dictamen_pi"."estado" IS 'pendiente | emitido | no_requerido';

COMMENT ON TABLE "revision_expediente" IS 'Ciclos de completitud (Comité asistente o Gestora VIE)';

COMMENT ON COLUMN "revision_expediente"."etapa" IS 'comite | vie';

COMMENT ON COLUMN "revision_expediente"."resultado" IS 'en_revision | completo | devuelto';

COMMENT ON COLUMN "revision_checklist"."codigo_item" IS 'FORMULARIO, PLAN, PRESUPUESTO, ADJUNTOS, DICTAMEN_PI...';

COMMENT ON COLUMN "observacion"."etapa" IS 'comite | vie | cie';

COMMENT ON COLUMN "rubrica"."modalidad_aplica" IS 'fortalecimiento | basica_aplicada | desarrollo_tecnologico';

COMMENT ON COLUMN "rubrica_criterio"."seccion" IS 'Ej. Grupo investigador, Plan de acción';

COMMENT ON TABLE "rubrica_nivel" IS 'Descriptores oficiales de la rúbrica';

COMMENT ON COLUMN "rubrica_nivel"."puntaje" IS '0, 6, 8 o 10';

COMMENT ON COLUMN "rubrica_nivel"."etiqueta" IS 'deficiente | regular | bueno | excelente';

COMMENT ON TABLE "evaluacion" IS 'Evaluación independiente por evaluador';

COMMENT ON COLUMN "evaluacion"."instancia" IS 'comite | cie';

COMMENT ON COLUMN "evaluacion"."estado" IS 'pendiente | en_progreso | completada';

COMMENT ON COLUMN "evaluacion_puntaje"."puntaje_sugerido_ia" IS 'Opcional; editable por humano';

COMMENT ON COLUMN "evaluacion_puntaje"."justificacion" IS 'Obligatoria según rúbrica oficial';

COMMENT ON TABLE "resultado_comite" IS 'Oficio consolidado del Comité tras las evaluaciones individuales';

COMMENT ON COLUMN "resultado_comite"."recomendacion" IS 'recomendada | no_recomendada';

COMMENT ON TABLE "sesion_consejo" IS 'Sesión citada en formatos de acuerdo 7/8';

COMMENT ON COLUMN "sesion_consejo"."tipo" IS 'ordinaria | extraordinaria | consulta_formal';

COMMENT ON COLUMN "aval_consejo"."resultado" IS 'aprobado | rechazado';

COMMENT ON TABLE "comunicacion_institucional" IS 'Comunicación formal (Dirección Escuela→VIE / Dirección Investigación→coordinador)';

COMMENT ON COLUMN "comunicacion_institucional"."tipo" IS 'aval_a_vie | notificacion_resolucion | otro';

COMMENT ON COLUMN "resolucion_cie"."resultado" IS 'aprobada | rechazada';

COMMENT ON TABLE "notificacion" IS 'Campana interna del sistema (distinta de comunicación formal)';

ALTER TABLE "usuario" ADD FOREIGN KEY ("id_escuela") REFERENCES "escuela" ("id_escuela") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "usuario_rol" ADD FOREIGN KEY ("id_usuario") REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "usuario_rol" ADD FOREIGN KEY ("id_rol") REFERENCES "rol" ("id_rol") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "convocatoria" ADD FOREIGN KEY ("id_publicada_por") REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "convocatoria_hito" ADD FOREIGN KEY ("id_convocatoria") REFERENCES "convocatoria" ("id_convocatoria") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "propuesta" ADD FOREIGN KEY ("id_convocatoria") REFERENCES "convocatoria" ("id_convocatoria") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "propuesta" ADD FOREIGN KEY ("id_coordinador") REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

